/// <summary>
/// §7.2. A knob the declared profile does not consult is refused, never cleared;
/// a consulted knob left unset takes the §7.2 default.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class CompositionConfig
{
    [JsonPropertyName("profile")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public CompositionProfile? Profile { get; set; }

    /// <summary>
    /// Consulted by sequential/first_deny only; refused under any other profile (§7.7.3).
    /// </summary>
    [JsonPropertyName("on_approval")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public OnApproval? OnApproval { get; set; }

    /// <summary>
    /// Consulted by parallel/unanimous only.
    /// </summary>
    [JsonPropertyName("on_disagreement")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ConflictResolution? OnDisagreement { get; set; }

    /// <summary>
    /// Consulted by parallel/strictest only.
    /// </summary>
    [JsonPropertyName("on_transform_conflict")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ConflictResolution? OnTransformConflict { get; set; }
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class ApprovalConfig
{
    /// <summary>
    /// §9. A registered approval resolver by reference, or null: liftable denies
    /// stay denies.
    /// </summary>
    [JsonPropertyName("resolver")]
    [JsonConverter(typeof(OptionalJsonConverter<string?>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<string?> Resolver { get; set; }

    /// <summary>
    /// §9 redaction seam. A registered approval redactor by reference, or null.
    /// </summary>
    [JsonPropertyName("redactor")]
    [JsonConverter(typeof(OptionalJsonConverter<string?>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<string?> Redactor { get; set; }
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class PostureConfig
{
    /// <summary>
    /// §13.1. Must equal the posture the host's code implements.
    /// </summary>
    [JsonPropertyName("tool_seam_host_error")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ToolSeamHostError? ToolSeamHostError { get; set; }
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class TimeoutsConfig
{
    /// <summary>
    /// §7 interceptor bound; default 5000. null means unbounded and must be written out.
    /// </summary>
    [JsonPropertyName("interceptor_ms")]
    [JsonConverter(typeof(OptionalJsonConverter<BigInteger, BigIntegerJsonConverter>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<BigInteger?> InterceptorMs { get; set; }

    /// <summary>
    /// §9 resolver bound; defaults to the value of interceptor_ms.
    /// </summary>
    [JsonPropertyName("approval_resolver_ms")]
    [JsonConverter(typeof(OptionalJsonConverter<BigInteger, BigIntegerJsonConverter>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<BigInteger?> ApprovalResolverMs { get; set; }
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class RecordsConfig
{
    /// <summary>
    /// In-memory record buffer bound; null (the default) is unbounded. The maximum
    /// is 2^53 - 1 so the resolved document always canonicalises (§4.4).
    /// </summary>
    [JsonPropertyName("max_buffered")]
    [JsonConverter(typeof(OptionalJsonConverter<BigInteger, BigIntegerJsonConverter>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<BigInteger?> MaxBuffered { get; set; }
}

[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class FailureConfig
{
    /// <summary>
    /// §6.3.1. The document default every binding's on_error inherits. deny keeps
    /// the §6.3 substituted deny; continue substitutes an allow carrying
    /// host_warning:control_failed and records the cause in substituted_for.
    /// </summary>
    [JsonPropertyName("on_error")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public OnError? OnError { get; set; }
}

/// <summary>
/// Host configuration (§7.1). Every member is OPTIONAL; defaults are the values
/// the specification already names and fail closed.
/// </summary>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed class Configuration
{
    /// <summary>
    /// §8.
    /// </summary>
    [JsonPropertyName("mode")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Mode? Mode { get; set; }

    [JsonPropertyName("composition")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public CompositionConfig? Composition { get; set; }

    /// <summary>
    /// §10.1: "jcs-sha256" (the default), a registered custom provider name
    /// (^[a-z][a-z0-9_-]{0,63}$, never a jcs prefix), or null (identity-unbound).
    /// </summary>
    [JsonPropertyName("identity_provider")]
    [JsonConverter(typeof(OptionalJsonConverter<string?>))]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
    public Optional<string?> IdentityProvider { get; set; }

    [JsonPropertyName("approval")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public ApprovalConfig? Approval { get; set; }

    [JsonPropertyName("posture")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public PostureConfig? Posture { get; set; }

    [JsonPropertyName("timeouts")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public TimeoutsConfig? Timeouts { get; set; }

    [JsonPropertyName("records")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public RecordsConfig? Records { get; set; }

    [JsonPropertyName("failure")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public FailureConfig? Failure { get; set; }
}

